<?php
namespace App\Filament\Resources\ProjectResource\RelationManagers;
use App\Models\{ActualCost,Party,Payment}; use App\Services\BudgetingService; use Filament\Forms; use Filament\Resources\RelationManagers\RelationManager; use Filament\Tables; use Filament\Tables\Table;
class ProjectPaymentsRelationManager extends RelationManager { protected static string $relationship='payments'; protected static ?string $title='Payments'; public function isReadOnly():bool{return false;} public function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('party.name')->label('Vendor'),Tables\Columns\TextColumn::make('amount'),Tables\Columns\TextColumn::make('currency'),Tables\Columns\TextColumn::make('project_amount')->label('Project amount'),Tables\Columns\TextColumn::make('status')->badge(),Tables\Columns\TextColumn::make('payment_date')->date()])->headerActions([Tables\Actions\Action::make('recordPayment')->label('Record payment')->icon('heroicon-o-plus')->form(fn()=>[Forms\Components\Select::make('party_id')->options(Party::withoutGlobalScopes()->where('company_id',$this->getOwnerRecord()->company_id)->pluck('name','id'))->required()->searchable(),Forms\Components\TextInput::make('amount')->numeric()->required(),Forms\Components\TextInput::make('currency')->default($this->getOwnerRecord()->currency)->required(),Forms\Components\TextInput::make('project_amount')->numeric()->required(),Forms\Components\DatePicker::make('payment_date')->default(now())->required(),Forms\Components\TextInput::make('reference_number'),Forms\Components\Select::make('payment_method')->options(['cash'=>'Cash','bank_transfer'=>'Bank transfer','cheque'=>'Cheque','card'=>'Card'])])->action(fn(array $data)=>app(BudgetingService::class)->recordPayment(auth()->user(),$this->getOwnerRecord(),$data))])->actions([Tables\Actions\Action::make('allocate')->icon('heroicon-o-arrow-right-circle')->tooltip('Allocate to approved cost')->visible(fn(Payment $r)=>$r->status==='completed')->form(fn(Payment $r)=>[Forms\Components\Select::make('actual_cost_id')->options(ActualCost::withoutGlobalScopes()->where('project_id',$r->project_id)->where('party_id',$r->party_id)->where('status','approved')->pluck('name','id'))->required(),Forms\Components\TextInput::make('payment_amount')->numeric()->required(),Forms\Components\TextInput::make('actual_cost_amount')->numeric()->required(),Forms\Components\TextInput::make('project_amount')->numeric()->required()])->action(function(Payment $r,array $data){$cost=ActualCost::withoutGlobalScopes()->findOrFail($data['actual_cost_id']);unset($data['actual_cost_id']);return app(BudgetingService::class)->allocatePayment(auth()->user(),$r,$cost,$data);}),Tables\Actions\Action::make('void')->icon('heroicon-o-no-symbol')->tooltip('Void unallocated payment')->color('danger')->visible(fn(Payment $r)=>$r->status==='completed'&&!$r->allocations()->exists())->form([Forms\Components\Textarea::make('reason')->required()])->action(fn(Payment $r,array $data)=>app(BudgetingService::class)->voidPayment(auth()->user(),$r,$data['reason']))]);} }
